local LuaClass = require("Core/LuaClass")
local UIViewModel = require("UI/UIViewModel")
local UIBindableList = require("UI/UIBindableList")
local RoomItemVM = require("Game/House/VM/Item/HouseInfoRoomItemVM")
local HouseLocalDef = require("Game/House/HouseLocalDef")
---@class HouseInfoInviteFriendsWinVM : UIViewModel
local HouseInfoRoomAllPanelVM = LuaClass(UIViewModel)

function HouseInfoRoomAllPanelVM:Ctor()
    self.RoomList = UIBindableList.New(RoomItemVM)
    self.BtnRoomVisibility = false
    self.MemberRoomList = {}
    self.TextButton = HouseLocalDef.HouseArmyRoom.ArmyCreateHouseButton
    self.HasRoom = false
end


function HouseInfoRoomAllPanelVM:UpdateVM(MsgBody)
    if MsgBody and #MsgBody > 0 then
        local function SortByIndex(Lv, Rv)                                                          --升序排序
            return Lv.Index < Rv.Index
        end
        
        table.sort(MsgBody, SortByIndex)
        if _G.HouseInfoMgr.MajorMemberHouseID > 0 then
            self.TextButton = HouseLocalDef.HouseArmyRoom.BackToHome
            self.HasRoom = true
        end
        local RoomIndex = MsgBody[#MsgBody].Index   --获取最大的Index值
        local RoomNum = #MsgBody
        local j = 1
        for i = 1, RoomIndex do                     --填充空房
            if j <= RoomNum and i == MsgBody[j].Index then
                j = j + 1
            else
                table.insert(MsgBody, {Index = i})
            end 
        end
        self.MemberRoomList = MsgBody
        self.RoomList:UpdateByValues(MsgBody)
        self.BtnRoomVisibility = true
        _G.HouseMineMainPanelVM.CommEmptyVisibility = false
        _G.HouseMineMainPanelVM.RoomAllPanelVisibility = true
    else
        _G.HouseMineMainPanelVM.CommEmptyVisibility = true
        _G.HouseMineMainPanelVM.RoomAllPanelVisibility = false
    end
end





return HouseInfoRoomAllPanelVM